[PASS] testIncorrectTransferRejection() (gas: 75369)
Logs:
  Transfer should have succeeded but failed. Token still owned by: 0x7FA9385bE102ac3EAc297483Dd6233D62b3e1496

ValidReceiver::onERC721Received(OwnershipNFTsTest: [0x7FA9385bE102ac3EAc297483Dd6233D62b3e1496], OwnershipNFTsTest: [0x7FA9385bE102ac3EAc297483Dd6233D62b3e1496], 1, 0x)
    │   │   └─ ← [Return] 0x150b7a02
    │   └─ ← [Revert] revert: bad nft transfer received data

Suite result: ok. 1 passed; 0 failed; 0 skipped; finished in 720.04µs (162.46µs CPU time)

//test setup
 function setUp() public {
        seawater = new MockSeawaterAMM();
        nft = new OwnershipNFTs("TestNFT", "TNFT", "http://test-uri.com", ISeawaterAMM(address(seawater)));
        validReceiver = new ValidReceiver();
    }

// test function
function testIncorrectTransferRejection() public {
        address owner = address(this);
        address recipient = address(validReceiver);
        uint256 tokenId = 1;

        // Mint a token to the owner
        seawater.mint(owner, tokenId);

        // Attempt to transfer the token to the valid receiver
        vm.expectRevert("bad nft transfer received data");
        nft.safeTransferFrom(owner, recipient, tokenId);

        // Check that the token is still owned by the original owner
        assertEq(nft.ownerOf(tokenId), owner);

        emit log_named_address("Transfer should have succeeded but failed. Token still owned by", owner);
    }
```

## Recommended Mitigation Steps
To fix this vulnerability, the condition in the require statement should be inverted. The corrected code should be:
```
require(
    data == IERC721TokenReceiver.onERC721Received.selector,
    "bad nft transfer received data"
);
```











