        //@audit added
        tokenIdToOwner[_tokenId] = _to;
    }

    function transferFrom(address _from, address _to, uint256 _tokenId, bytes calldata /* _data */ ) external payable {
        // checks that the user is authorised
        _transfer(_from, _to, _tokenId);
    }

